{
  "spans": [
    {
      "label": "QUOTE",
      "head": "ལུས་ནི་གཅིག་པུ་བྱུང་བ་ཡང༌། ། ལྷན་ཅིག་སྐྱེས་པའི་ཤ་རུས་ཀྱང༌། ། འཇིག་སྟེ་སོ་སོར་གྱེས་འགྱུར་ན། ། མཛའ་བ་གཞན་ལྟ་སྨོས་ཅི་དགོས། ། དེ་བས་འཇིག་རྟེན་བསམ་པ་གཏང༌། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཕ་ནི་བུ་ཉིད་མ་ནི་ཆུང་མ་ཉིད། ། སྐྱེ་བོ་དགྲར་གྱུར་པ་ཡང་མེད་ཉིད་དེ། ། བཟློག་པ་ཉིད་དུ་མཆི་བས་དེ་སླད་དུ། ། འཇིག་རྟེན་འདི་ན་ངེས་པ་འགའ་མ་མཆིས།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "གང་ཞིག་མེད་མིན་ཡོད་མིན་ཡོད་མེད་མ་ཡིན་ཡོད་མེད་ལས་གཞན་དུའང༌། ། བརྟག་པར་མི་ནུས་ངེས་ཚིག་དང་བྲལ་ສོ་སོ་རང་གིས་རིག་ཞི་བ། ། དྲི་མེད་ཡེ་ཤེས་འོད་ཟེར་སྣང་ལྡན་དམིགས་པ་ཀུན་ལ་ཆགས་པ་དང༌། ། སྡང་དང་རབ་རིབ་རྣམ་པར་འཇོམས་མཛད་དམ་ཆོས་ཉི་མ་དེ་ལ་འདུད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྩང་ནག་པའི་ཞལ་ནས།",
      "head": "དེ་ལྟར་སོང་ན་ཆོས་ཐམས་ཅད་",
      "tail": "གསུངས་པ་ལགས་པར་གདའ།"
    },
    {
      "label": "QUOTE",
      "frame": "བླ་མ་རིན་པོ་ཆེའི་ཞལ་ནས།",
      "head": "ཁམས་གསུམ་འཁོར་བ་སྡུག་བསྔལ་",
      "tail": "གཉིས་ལས་བྱུང་བ་ཡིན་གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "དུས་གསུམ་བདག་ཉིད་བདེ་ཆེན་བླ་མ་ནི། །སོགས་པ་གསུངས།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ཉིད་ངོ་བོ་ཉིད་ཀྱི་སྐུ། །ལ་སོགས་པ་གསུངས།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ངོ་བོ་གང་ཡིན་ན། ངོ་བོ། གཟུགས་མེད་མཐོང་བ་པོ་ཡང་མེད། །ལ་སོགས་པ་གསུང་ན།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཇི་ལྟར་ཚོན་རྐྱེན་སྣ་ཚོགས་ཀྱིས། ། ནོར་བུ་དེ་དངོས་མིན་པར་སྣང༌། ། དེ་བཞིན་འགྲོ་རྐྱེན་སྣ་ཚོགས་ཀྱིས། ། ཁྱབ་བདག་དེ་དངོས་མིན་པར་སྣང༌། ། བགྱི་བ་གསུངས་ན།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "མ་རིག་པའི་རྐྱེན་གྱིས་འདུ་བྱེད་",
      "tail": "བར་དུ་འབྱུང་བར་གསུངས།"
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ཞི་བ་ནི་ཞི་གནས་ཏེ། ། ཆོས་ཤེས་པ་ནི་ལྷག་མཐོང་ཡིན། ། བགྱི་བ་གསུངས།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཞི་གནས་རབ་ཏུ་ལྡན་པའི་ལྷག་མཐོང་གིས། ། ཉོན་མོངས་རྣམ་པར་འཇོམས་པར་ཤེས་བྱས་ནས། ། ཐོག་མར་ཞི་གནས་བཙལ་བྱ་དེ་ཡང་ནི། ། འཇིག་རྟེན་ཆགས་པ་མེད་ལ་མངོན་དགས་འགྲུབ། ། བགྱི་བ་གསུང་ན།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "རྒས་པ་མཐོང་ན་ན་བ་སྡུག་བསྔལ་སྟེ། །སེམས་དང་བྲལ་བའི་འཆི་བ་མཐོང་ནས་ནི། །འཇིག་རྟེན་སྤྱོད་པ་བདག་གིས་ནུས་རེ་རྐན། །གསུང་ནས་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བླ་མ་རིན་པོ་ཆེའི་ཞལ་སྔ་ནས།",
      "head": "འཁོར་བ་སྡུག་བསྔལ་གྱི་རྒྱ་མཚོ་",
      "tail": "མེད་པ་ལས་བྱུང་བ་ཡིན་གསུངས་ཏེ།"
    },
    {
      "label": "QUOTE",
      "head": "བདག་ཡོད་ན་ནི་གཞན་དུ་ཤེས། ། བདག་གཞན་ཆ་ལས་འཛིན་དང་སྡང༌། ། དེ་གཉིས་དང་ནི་འབྲེལ་པ་ལས། ། ཉེས་པ་ཐམས་ཅད་འབྱུང་བ་ཡིན། ། ཉེས་ཀུན་དེ་ཡི་རྩ་བ་ཅན། ། དེ་ཡང་འཇིག་ཚོགས་ལྟ་བ་ཡིན། ། བགྱི་བ་གསུངས་ན་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ཉིད་ངོ་བོ་ཉིད་ཀྱི་སྐུ། ། ལྷུན་གྱིས་གྲུབ་ཅིང་འདུས་མ་བྱས། ། སྨྲ་བསམ་ཤེས་བརྗོད་ཡུལ་ལས་འདས། ། རིན་པོ་ཆེ་ལ་ཕྱག་འཚལ་ལོ། ། གསུངས་པའི་དོན་ཡང་དེ་ཡིན།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དུས་གསུམ་བདག་ཉིད་བདེ་ཆེན་བླ་མ་ནི། ། ཁྱབ་དང་གཟུགས་ཅན་མ་ཡིན་འགྲོ་འོང་མེད། ། ཆོས་སྐུ་རང་བཞིན་ལྷུན་གྲུབ་ངོ་བོ་ཉིད། ། མི་འགྱུར་རྡོ་རྗེའི་སྐུ་ལ་ཕྱག་འཚལ་ལོ། ། གསུངས་པས་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཇི་ལྟར་ནམ་མཁའ་མེ་རྣམས་ཀྱིས། ། སྔོན་ཆད་ནམ་ཡང་ཚིག་པ་མེད། ། དེ་བཞིན་འདི་ནི་སྐྱེ་བ་དང༌། ། རྒ་དང་ན་བའི་མེས་མི་འཚིག ། བགྱི་བ་ལ་སོགས་པ་གསུངས་ན།",
      "tail": ""
    }
  ]
}
